import type { OpenAPISpec, OpenAPISchema, NormalizedOperation } from '../types/openapi.js';
import { OpenAPILoader } from './openapi-loader.js';

export class TypeGenerator {
  /**
   * Generates TypeScript interfaces and Zod runtime validation schemas
   */
  static generate(spec: OpenAPISpec): { typeScript: string; zod: string } {
    const operations = OpenAPILoader.extractOperations(spec);
    const tsLines: string[] = [
      '// Generated by AgentSpec',
      '// Do not edit manually',
      ''
    ];

    const zodLines: string[] = [
      '// Generated by AgentSpec',
      '// Runtime Zod validation schemas',
      "import { z } from 'zod';",
      ''
    ];

    for (const op of operations) {
      const pascalId = this.toPascalCase(op.id);

      // 1. Parameters Interface & Zod Schema
      const paramProps: string[] = [];
      const zodParamProps: string[] = [];

      for (const p of op.parameters) {
        const isReq = p.required ? '' : '?';
        const tsType = this.schemaToTsType(p.schema);
        const zSchema = this.schemaToZod(p.schema, p.required ?? false);

        paramProps.push(`  /** ${p.description || p.name} (${p.in}) */`);
        paramProps.push(`  ${p.name}${isReq}: ${tsType};`);
        zodParamProps.push(`  ${p.name}: ${zSchema},`);
      }

      tsLines.push(`export interface ${pascalId}Parameters {`);
      if (paramProps.length > 0) {
        tsLines.push(paramProps.join('\n'));
      }
      tsLines.push('}\n');

      zodLines.push(`export const ${pascalId}ParametersSchema = z.object({`);
      if (zodParamProps.length > 0) {
        zodLines.push(zodParamProps.join('\n'));
      }
      zodLines.push('});\n');
      zodLines.push(`export type ${pascalId}ParametersValidated = z.infer<typeof ${pascalId}ParametersSchema>;\n`);

      // 2. Request Body Interface & Zod Schema
      if (op.requestBodySchema) {
        const bodyType = this.schemaToTsType(op.requestBodySchema);
        const bodyZod = this.schemaToZod(op.requestBodySchema, op.requestBodyRequired);

        tsLines.push(`export type ${pascalId}RequestBody = ${bodyType};\n`);
        zodLines.push(`export const ${pascalId}RequestBodySchema = ${bodyZod};\n`);
      } else {
        tsLines.push(`export type ${pascalId}RequestBody = undefined;\n`);
        zodLines.push(`export const ${pascalId}RequestBodySchema = z.undefined();\n`);
      }

      // 3. Response Schema (200 / default)
      const successSchema = op.responseSchemas['200'] || op.responseSchemas['201'] || Object.values(op.responseSchemas)[0];
      if (successSchema) {
        const respType = this.schemaToTsType(successSchema);
        const respZod = this.schemaToZod(successSchema, true);

        tsLines.push(`export type ${pascalId}Response = ${respType};\n`);
        zodLines.push(`export const ${pascalId}ResponseSchema = ${respZod};\n`);
      } else {
        tsLines.push(`export type ${pascalId}Response = Record<string, unknown>;\n`);
        zodLines.push(`export const ${pascalId}ResponseSchema = z.record(z.unknown());\n`);
      }
    }

    return {
      typeScript: tsLines.join('\n'),
      zod: zodLines.join('\n')
    };
  }

  private static toPascalCase(str: string): string {
    return str
      .replace(/[^a-zA-Z0-9_]/g, '_')
      .split('_')
      .filter(Boolean)
      .map(part => part.charAt(0).toUpperCase() + part.slice(1))
      .join('');
  }

  private static schemaToTsType(schema?: OpenAPISchema): string {
    if (!schema) return 'unknown';

    if (schema.enum && Array.isArray(schema.enum)) {
      return schema.enum.map(e => JSON.stringify(e)).join(' | ');
    }

    const type = Array.isArray(schema.type) ? schema.type[0] : schema.type;

    switch (type) {
      case 'string':
        return 'string';
      case 'number':
      case 'integer':
        return 'number';
      case 'boolean':
        return 'boolean';
      case 'array':
        return `${this.schemaToTsType(schema.items)}[]`;
      case 'object': {
        if (!schema.properties || Object.keys(schema.properties).length === 0) {
          return 'Record<string, unknown>';
        }
        const props: string[] = [];
        for (const [k, v] of Object.entries(schema.properties)) {
          const req = schema.required?.includes(k) ? '' : '?';
          props.push(`    ${k}${req}: ${this.schemaToTsType(v)};`);
        }
        return `{\n${props.join('\n')}\n  }`;
      }
      default:
        return 'unknown';
    }
  }

  private static schemaToZod(schema?: OpenAPISchema, required = true): string {
    if (!schema) {
      return required ? 'z.unknown()' : 'z.unknown().optional()';
    }

    let baseZod = 'z.unknown()';

    if (schema.enum && Array.isArray(schema.enum)) {
      const literals = schema.enum.map(e => `z.literal(${JSON.stringify(e)})`).join(', ');
      baseZod = `z.union([${literals}])`;
    } else {
      const type = Array.isArray(schema.type) ? schema.type[0] : schema.type;

      switch (type) {
        case 'string':
          baseZod = 'z.string()';
          if (schema.minLength !== undefined) baseZod += `.min(${schema.minLength})`;
          if (schema.maxLength !== undefined) baseZod += `.max(${schema.maxLength})`;
          break;
        case 'integer':
        case 'number':
          baseZod = type === 'integer' ? 'z.number().int()' : 'z.number()';
          if (schema.minimum !== undefined) baseZod += `.min(${schema.minimum})`;
          if (schema.maximum !== undefined) baseZod += `.max(${schema.maximum})`;
          break;
        case 'boolean':
          baseZod = 'z.boolean()';
          break;
        case 'array':
          baseZod = `z.array(${this.schemaToZod(schema.items, true)})`;
          break;
        case 'object': {
          if (!schema.properties || Object.keys(schema.properties).length === 0) {
            baseZod = 'z.record(z.unknown())';
          } else {
            const props: string[] = [];
            for (const [k, v] of Object.entries(schema.properties)) {
              const isReq = schema.required?.includes(k) ?? false;
              props.push(`    ${k}: ${this.schemaToZod(v, isReq)}`);
            }
            baseZod = `z.object({\n${props.join(',\n')}\n  })`;
          }
          break;
        }
        default:
          baseZod = 'z.unknown()';
      }
    }

    if (!required) {
      baseZod += '.optional()';
    }

    return baseZod;
  }
}
